class Workflow:
    def max_sum_subarray(self, arr, k):
        n = len(arr)
        if n < k:
            return -1
        max_sum = sum(arr[:k])
        window_sum = max_sum
        for i in range(n - k):
            window_sum = window_sum - arr[i] + arr[i + k]
            max_sum = max(max_sum, window_sum)
        return max_sum
